import{_ as o,o as t,c as r,a2 as d}from"./chunks/framework.CNDaxUod.js";const h=JSON.parse('{"title":"Cloud sync rollout checklist","description":"","frontmatter":{},"headers":[],"relativePath":"operations/cloud-sync-rollout.md","filePath":"operations/cloud-sync-rollout.md","lastUpdated":1788607300000}'),a={name:"operations/cloud-sync-rollout.md"};function n(s,e,l,c,i,u){return t(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="cloud-sync-rollout-checklist" tabindex="-1">Cloud sync rollout checklist <a class="header-anchor" href="#cloud-sync-rollout-checklist" aria-label="Permalink to &quot;Cloud sync rollout checklist&quot;">​</a></h1><p>Cloud sync spans three repositories and two independent feature flags. It must remain fail-closed until every backend dependency and the SSO client entry are ready.</p><h2 id="scope-and-production-values" tabindex="-1">Scope and production values <a class="header-anchor" href="#scope-and-production-values" aria-label="Permalink to &quot;Scope and production values&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Production value</th></tr></thead><tbody><tr><td>Web Resume origin</td><td><code>https://resume.yunle.fun</code></td></tr><tr><td>SSO client / app</td><td><code>web-resume-web</code> / <code>web-resume</code></td></tr><tr><td>Redirect</td><td><code>https://resume.yunle.fun/user</code></td></tr><tr><td>Scope</td><td><code>identity:bootstrap</code></td></tr><tr><td>Drive BFF prefix</td><td><code>https://drive.yunle.fun/api/v1/web-resume</code></td></tr><tr><td>Metadata collection</td><td><code>web_resume_documents</code> (<code>ADMINONLY</code>)</td></tr><tr><td>Resume object limit</td><td>2 MiB</td></tr><tr><td>Trash retention</td><td>30 days</td></tr></tbody></table><p>The only registered development origin is <code>https://resume.yunle.localhost:3455</code>, with redirect <code>/user</code>. Preview domains and mirrors must keep cloud sync disabled.</p><h2 id="pre-deployment-checks" tabindex="-1">Pre-deployment checks <a class="header-anchor" href="#pre-deployment-checks" aria-label="Permalink to &quot;Pre-deployment checks&quot;">​</a></h2><ol><li>In <code>www.yunle.fun</code>, create <code>web_resume_documents</code> with <code>ADMINONLY</code> ACL and all indexes declared by <code>cloudfunctions/user-storage-api/web-resume-resources.js</code>.</li><li>Generate two independent random service tokens of at least 32 bytes. Configure <code>WEB_RESUME_STORAGE_INTERNAL_TOKEN</code> on <code>user-storage-api</code> and the Drive BFF; configure <code>WEB_RESUME_SWEEPER_INTERNAL_TOKEN</code> on both storage functions. Never expose either token through a public or <code>VITE_</code> variable.</li><li>Keep the private COS bucket private. Its CORS rule must allow the exact production origin, <code>PUT</code>, and <code>Content-Type</code>; do not use wildcard origins or credentialed CORS.</li><li>Deploy the updated <code>user-storage-api</code> and private <code>web-resume-storage-sweeper</code>, then verify a dry storage reserve/finalize/delete cycle and the sweeper&#39;s bounded result counters.</li><li>Deploy Drive with all <code>NUXT_WEB_RESUME_*</code> values configured but <code>NUXT_WEB_RESUME_ENABLED=false</code>. Confirm its session store, rate-limit collection, CloudBase credentials, and CSRF secret are healthy.</li><li>Review the generated unsigned production and development Registry drafts in <code>www.yunle.fun/specs/sso-client-registry-platform/drafts/</code>. Complete the existing approval and signed Registry publication workflow; do not hand-edit or publish an unsigned draft.</li></ol><h2 id="enablement-order" tabindex="-1">Enablement order <a class="header-anchor" href="#enablement-order" aria-label="Permalink to &quot;Enablement order&quot;">​</a></h2><ol><li>Enable <code>NUXT_WEB_RESUME_ENABLED=true</code> on Drive. Before the frontend is enabled, verify anonymous calls return <code>401</code>, disallowed origins return <code>403</code>, and the read-only Drive connector works for an authorized test account.</li><li>Run a real test account through SSO, first save, autosave, download, conflict copy, Trash, restore, logout, and a second-device session. Verify the raw YAML checksum and shared quota deltas.</li><li>Build Web Resume with <code>VITE_YLF_CLOUD_ENABLED=true</code> and the production values in <code>apps/web/.env.example</code>. Enable the Cloudflare Pages runtime flag <code>YLF_CLOUD_API_ENABLED=true</code> in the same release.</li><li>Run browser smoke tests on desktop and mobile. Desktop must show the account control in the top-right and “My” navigation; mobile must show only the bottom “My” entry.</li><li>Observe session exchange failures, storage reserve/finalize failures, conflict-copy rate, quota changes, and sweeper errors before expanding traffic.</li></ol><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Disable <code>YLF_CLOUD_API_ENABLED</code> first to close the same-origin proxy, then disable <code>NUXT_WEB_RESUME_ENABLED</code>. A later frontend build may set <code>VITE_YLF_CLOUD_ENABLED=false</code> to hide the UI. Keep the Registry entry, metadata collection, private objects, and sweeper in place so existing user data remains recoverable; rollback must not delete cloud resumes.</p><h2 id="account-only-rollout" tabindex="-1">Account-only rollout <a class="header-anchor" href="#account-only-rollout" aria-label="Permalink to &quot;Account-only rollout&quot;">​</a></h2><p>Set <code>VITE_YLF_LOGIN_ENABLED=true</code> in the production Pages build and <code>NUXT_WEB_RESUME_LOGIN_ENABLED=true</code> in Drive. Keep the cloud storage flags disabled. Deploy <code>workers/wrangler.toml</code> for the main domain: the Worker handles <code>/api/*</code> directly before proxying static assets to <code>resume.elpsy.cn</code>, preserving the registered Origin. Mirror API flags remain off. Verify anonymous session requests return 401 and document requests return 404.</p><p>For the local Apps iOS simulator, sign in to a test account, open <code>https://resume.yunle.fun/user</code> in the host web view, and exercise consent, cancellation, session reload, and logout. Signing in must not upload a resume or replace local contact details.</p><p>The Cloudflare Page Rule for <code>https://drive.yunle.fun/api/v1/web-resume/*</code> must set SSL to <code>strict</code>. The zone-level Flexible setting otherwise causes an HTTP-to-HTTPS redirect loop on Worker subrequests. Keep certificate validation enabled.</p>',15)])])}const m=o(a,[["render",n]]);export{h as __pageData,m as default};
